--[[
    PHANTIX — Nebula Luxe
    Version: 0.4.0 FINAL (Nebula Luxe Colorwave)

    Oberfläche (unverändert) plus Riddle-Engine:
      1) Lokale Datenbank SAB_DB wird zuerst durchsucht.
      2) Nur ohne vollständigen lokalen Treffer und nur bei eingeschaltetem
         "AI Fallback" wird der Cloudflare-Worker gefragt.
      3) Optional: "Riddle Listener" liest Global-Announcements mit.
    Antworten erscheinen nur im Feld LAST CODE. Es wird nichts automatisch
    eingetippt, abgeschickt oder eingelöst.

    Token (nie im Code veröffentlichen): vor dem Start in der Executor-Umgebung setzen
        getgenv().PHANTIX_AUTH_TOKEN = "<dein neuer Token>"
    oder alternativ AI_CONFIG.AuthToken unten eintragen.

    Start: Script ausführen.
    Minimieren: kompakte PHANTIX-Leiste mit AN/AUS-Demo-Schalter; + stellt wieder her.
    Mobile: großer, verschiebbarer P-Button; Antippen blendet das Menü ein/aus.
    Beenden: Schließen (×) oder PHANTIX_Stop() in der Laufzeitumgebung.
]]

