-- ── Allgemeine Hilfsfunktionen ───────────────────────────────────────────
local function new(className, props, parent)
    local object = Instance.new(className)
    for property, value in pairs(props or {}) do
        object[property] = value
    end
    if parent then object.Parent = parent end
    return object
end

local function corner(object, radius)
    local item = Instance.new("UICorner")
    item.CornerRadius = UDim.new(0, radius or 8)
    item.Parent = object
    return item
end

local function stroke(object, color, thickness, transparency)
    local item = Instance.new("UIStroke")
    item.Color = color or Theme.Stroke
    item.Thickness = thickness or 1
    item.Transparency = transparency or 0
    item.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    item.Parent = object
    return item
end

local function tween(object, properties, duration)
    local item = TweenService:Create(
        object,
        TweenInfo.new(duration or 0.14, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
        properties
    )
    item:Play()
    return item
end

local function fontSize(size)
    return math.floor((size or 11) * FONT_SCALE + 0.5)
end

local function makeLabel(parent, text, size, color, font, alignment)
    return new("TextLabel", {
        BackgroundTransparency = 1,
        Text = text,
        TextSize = fontSize(size),
        TextColor3 = color or Theme.Text,
        Font = font or Enum.Font.GothamMedium,
        TextXAlignment = alignment or Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Center,
    }, parent)
end

-- Activated deckt Maus und Touch ab. Mehrfachbindungen werden vermieden.
local function bindClick(button, callback)
    button.Activated:Connect(callback)
end

local function applyGlass(frame, baseColor, transparency)
    local amount = transparency or 0.3
    frame.BackgroundColor3 = baseColor
    frame.BackgroundTransparency = amount

    local gradient = Instance.new("UIGradient")
    gradient.Rotation = 90
    gradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0.05),
        NumberSequenceKeypoint.new(0.5, amount),
        NumberSequenceKeypoint.new(1, math.min(amount + 0.15, 0.9)),
    })
    gradient.Parent = frame

    local rim = new("Frame", {
        Size = UDim2.new(1, -16, 0, 1),
        Position = UDim2.new(0, 8, 0, 1),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 0.65,
        BorderSizePixel = 0,
        ZIndex = frame.ZIndex + 1,
    }, frame)

    local rimGradient = Instance.new("UIGradient")
    rimGradient.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(0.5, 0.4),
        NumberSequenceKeypoint.new(1, 1),
    })
    rimGradient.Parent = rim
end

local function escapeRichText(value)
    local text = tostring(value or "")
    text = text:gsub("&", "&amp;")
    text = text:gsub("<", "&lt;")
    text = text:gsub(">", "&gt;")
    text = text:gsub('"', "&quot;")
    text = text:gsub("'", "&apos;")
    return text
end

-- ── P-Emblem: Neon-Look aus UI-Elementen (kein Roblox-Bild nötig) ─────────
-- Buchstabe mit Metall-Verlauf und grüner Neon-Kante.
local function stylePLetter(label)
    label.TextColor3 = Color3.fromRGB(255, 255, 255) -- Farbe kommt vom Verlauf

    local fill = Instance.new("UIGradient")
    fill.Rotation = 90
    fill.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(246, 240, 255)),
        ColorSequenceKeypoint.new(0.45, Theme.PurpleLight),
        ColorSequenceKeypoint.new(1, Theme.PurpleDim),
    })
    fill.Parent = label

    local edge = Instance.new("UIStroke")
    edge.Color = Theme.Emerald
    edge.Thickness = 1.5
    edge.Transparency = 0.1
    edge.ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual
    edge.Parent = label
end

-- Großes Emblem für einen runden Button: Orbit-Ring, P und Krone aus drei Steinen.
-- Alle Teile sind rein optisch (keine Eingabe), der Button behält Klick und Drag.
local function buildPEmblem(button, baseZ)
    local orbit = new("Frame", {
        Name = "Orbit",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.58),
        Size = UDim2.fromScale(0.84, 0.36),
        Rotation = -28,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = baseZ + 1,
    }, button)
    corner(orbit, 100)
    local orbitStroke = stroke(orbit, Theme.Emerald, 1.6, 0.12)
    local orbitGradient = Instance.new("UIGradient")
    orbitGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Theme.Emerald),
        ColorSequenceKeypoint.new(0.5, Theme.Cyan),
        ColorSequenceKeypoint.new(1, Theme.PurpleLight),
    })
    orbitGradient.Parent = orbitStroke

    local letter = makeLabel(button, "P", 25, Theme.Text, Enum.Font.GothamBlack, Enum.TextXAlignment.Center)
    letter.Name = "PLetter"
    letter.AnchorPoint = Vector2.new(0.5, 0.5)
    letter.Position = UDim2.fromScale(0.5, 0.6)
    letter.Size = UDim2.fromScale(1, 1)
    letter.ZIndex = baseZ + 2
    stylePLetter(letter)

    -- Krone: Band plus drei Steine (Quadrate, um 45° gedreht)
    local band = new("Frame", {
        Name = "CrownBand",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.27),
        Size = UDim2.fromScale(0.4, 0.05),
        BackgroundColor3 = Theme.PurpleLight,
        BorderSizePixel = 0,
        ZIndex = baseZ + 3,
    }, button)
    corner(band, 3)

    local gems = {
        { 0.34, 0.19, 0.13 },
        { 0.50, 0.14, 0.18 },
        { 0.66, 0.19, 0.13 },
    }
    for _, gem in ipairs(gems) do
        local stone = new("Frame", {
            Name = "CrownGem",
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(gem[1], gem[2]),
            Size = UDim2.fromScale(gem[3], gem[3]),
            Rotation = 45,
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            BorderSizePixel = 0,
            ZIndex = baseZ + 3,
        }, button)
        stroke(stone, Theme.Emerald, 1, 0.2)
        local stoneGradient = Instance.new("UIGradient")
        stoneGradient.Rotation = 90
        stoneGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(246, 240, 255)),
            ColorSequenceKeypoint.new(1, Theme.Purple),
        })
        stoneGradient.Parent = stone
    end
end

