    Name = "BrandGlow",
    BackgroundTransparency = 1,
    BorderSizePixel = 0,
    Image = "",
    ImageTransparency = 1,
    ScaleType = Enum.ScaleType.Fit,
    ZIndex = 12,
}, Header)
-- 0.99: praktisch unsichtbar, wird aber geladen und gerendert (sichtbar erst nach erfolgreicher Prüfung)
local BrandLogo = new("ImageLabel", {
    Name = "Brand",
    BackgroundTransparency = 1,
    BorderSizePixel = 0,
    Image = "",
    ImageTransparency = 0.99,
    ScaleType = Enum.ScaleType.Fit,
    ZIndex = 13,
}, Header)
local titleActive = false

local function roundInt(value)
    return math.floor(value + 0.5)
end

-- Logo und Glow werden immer gemeinsam und proportional platziert (Glow mittig hinter dem Logo).
local function placeTitle(x, y, width, height)
    BrandLogo.Position = UDim2.fromOffset(x, y)
    BrandLogo.Size = UDim2.fromOffset(width, height)
    local glowWidth = roundInt(width * TITLE_GLOW_SCALE)
    local glowHeight = roundInt(height * TITLE_GLOW_SCALE)
    BrandGlow.Position = UDim2.fromOffset(
        roundInt(x + (width - glowWidth) / 2),
        roundInt(y + (height - glowHeight) / 2)
    )
    BrandGlow.Size = UDim2.fromOffset(glowWidth, glowHeight)
end

local function applyTitleLayout(isMinimised)
    if isMinimised then
        placeTitle(26, 15, 94, 26)
    else
        placeTitle(24, 2, 140, 38)
    end
end
applyTitleLayout(false)

