-- ── Riddle-Controller: lokale Datenbank zuerst, dann optional Cloudflare ──────────
-- Ersetzt den früheren Demo-Handler. Schreibt Antworten ausschließlich in LAST CODE.
local PHANTIX_SOLVER = {}
do
    local aiEnabled = false
    local listenerEnabled = false
    local listenerConnection = nil
    local listenerResolving = false
    local generation = 0
    local pending = {}
    local recentAnnouncements = {}
    local lastAiAt = -1000
    local askedCount = 0
    local solvedCount = 0
    local MAX_QUESTION_LENGTH = 500 -- gleiche Grenze wie der Worker (MAX_Q_LEN)

    local function updateCounters()
        AskedStatVal.Text = tostring(askedCount)
        SolvedStatVal.Text = tostring(solvedCount)
    end

    local function getToken()
        local token = env.PHANTIX_AUTH_TOKEN
        if type(token) ~= "string" or token == "" then
            token = AI_CONFIG.AuthToken
        end
        if type(token) ~= "string" then return nil end
        token = token:gsub("^%s+", ""):gsub("%s+$", "")
        if token == "" or token:upper():find("PASTE", 1, true) then return nil end
        return token
    end

    local function getRequestFunction()
        local candidate = (syn and syn.request) or (http and http.request) or http_request or request
        if type(candidate) == "function" then return candidate end
        return nil
    end

    local function showAnswer(answer, sourceTag, detail)
        LastOutputBox.Text = answer
        solvedCount = solvedCount + 1
        updateCounters()
        logLine("[" .. sourceTag .. "] " .. answer .. (detail and ("  (" .. detail .. ")") or "") .. " — review it yourself; nothing is submitted.", Theme.Emerald)
    end

    -- Führt den HTTP-Aufruf in einem eigenen Thread aus und wartet höchstens "seconds".
    local function requestWithTimeout(requestFunction, requestTable, seconds)
        local finished, callOk, callResult = false, false, nil
        task.spawn(function()
            callOk, callResult = pcall(requestFunction, requestTable)
            finished = true
        end)
        local startedAt = os.clock()
        while not finished and os.clock() - startedAt < seconds do
            task.wait(0.1)
        end
        if not finished then return false, "timeout", true end
        return callOk, callResult, false
    end

    local function decodeJson(body)
        return HttpService:JSONDecode(body)
    end

    -- Rückgabe wie Engine.parseWorkerResponse
    local function askWorker(question, token, requestFunction, myGeneration)
        local requestTable = {
            Url = AI_CONFIG.WorkerUrl,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json",
                ["X-Auth-Token"] = token,
            },
            Body = HttpService:JSONEncode({ question = question }),
        }
        local result
        for attempt = 1, AI_CONFIG.MaxAttempts do
            local callOk, response, timedOut = requestWithTimeout(requestFunction, requestTable, AI_CONFIG.TimeoutSeconds)
            if timedOut then
                result = { ok = false, retry = true, message = "Cloudflare request timed out after " .. AI_CONFIG.TimeoutSeconds .. " s." }
            elseif not callOk then
                result = { ok = false, retry = true, message = "Request failed: " .. tostring(response):sub(1, 80) }
            elseif type(response) ~= "table" then
                result = { ok = false, retry = false, message = "Executor returned no usable HTTP response." }
            else
                local status = tonumber(response.StatusCode or response.Status or response.status_code)
                result = PHANTIX_ENGINE.parseWorkerResponse(status, response.Body or response.body, decodeJson)
            end
            if result.ok or not result.retry or attempt >= AI_CONFIG.MaxAttempts or generation ~= myGeneration then
                return result
            end
            logLine("Attempt " .. attempt .. " failed: " .. result.message .. " Retrying…", Theme.Warn)
            task.wait(1.5 * attempt)
            if generation ~= myGeneration or not aiEnabled then
                return { ok = false, retry = false, message = "cancelled" }
            end
        end
        return result
    end

    local function solveNow(text, sourceName, key, myGeneration)
        local localResult = PHANTIX_ENGINE.solveLocal(text)
        if localResult.complete then
            showAnswer(localResult.answer, "LOCAL", table.concat(localResult.breakdown, " | "))
            return
        end

        if localResult.answer then
            logLine("Local database knows only part of it (" .. table.concat(localResult.breakdown, " | ") .. "); not used as an answer.", Theme.Warn)
        else
            logLine("Not in local database.", Theme.Dim)
        end

        if not aiEnabled then
            logLine("AI fallback is OFF — enable it in Settings to ask Cloudflare.", Theme.Dim)
            return
        end
        local token = getToken()
        if not token then
            logLine("No AI token set. Use getgenv().PHANTIX_AUTH_TOKEN or AI_CONFIG.AuthToken (see file header).", Theme.Red)
            return
        end
        local requestFunction = getRequestFunction()
        if not requestFunction then
            logLine("This executor has no HTTP request function.", Theme.Red)
            return
        end
        local waitLeft = AI_CONFIG.CooldownSeconds - (os.clock() - lastAiAt)
        if waitLeft > 0 then
            logLine(string.format("AI cooldown: try again in %.1f s.", waitLeft), Theme.Warn)
            return
        end
        lastAiAt = os.clock()

        logLine("Asking Cloudflare AI (" .. tostring(sourceName) .. "): " .. text:sub(1, 60), Theme.PurpleLight)
        local result = askWorker(text, token, requestFunction, myGeneration)
        if generation ~= myGeneration or not aiEnabled then return end -- inzwischen ausgeschaltet/beendet
        if result.ok then
            showAnswer(result.answer, "AI")
        else
            LastOutputBox.Text = ""
            logLine("AI: " .. result.message, Theme.Red)
        end
    end

    function PHANTIX_SOLVER.solve(rawText, sourceName)
        local text = PHANTIX_ENGINE.clean(rawText)
        if text == "" then
            logLine("Type a riddle first.", Theme.Warn)
            return
        end
        if #text > MAX_QUESTION_LENGTH then
            logLine("Riddle is too long (maximum " .. MAX_QUESTION_LENGTH .. " characters).", Theme.Warn)
            return
        end
        local key = text:lower()
        if pending[key] then
            logLine("Duplicate ignored: this riddle is already being solved.", Theme.Dim)
            return
        end
        pending[key] = true
        askedCount = askedCount + 1
        updateCounters()
        LastOutputBox.Text = "" -- nie eine alte Antwort als Ergebnis dieser Frage stehen lassen
        local myGeneration = generation
        task.spawn(function()
            local ok, err = pcall(solveNow, text, sourceName or "manual", key, myGeneration)
            pending[key] = nil
            if not ok then
                logLine("Unexpected error: " .. tostring(err):sub(1, 100), Theme.Red)
            end
        end)
    end

    -- ── Global-Announcement-Listener ─────────────────────────────────────
    local function extractMessage(...)
        local best = ""
        for _, value in ipairs({ ... }) do
            if type(value) == "string" and #value > #best then
                best = value
            elseif type(value) == "table" then
                for _, field in ipairs({ "Text", "text", "Message", "message", "Title", "title", "Body", "body" }) do
                    local candidate = value[field]
                    if type(candidate) == "string" and #candidate > #best then best = candidate end
                end
            end
        end
        return PHANTIX_ENGINE.clean(best)
    end

    local function onAnnouncement(...)
        if not listenerEnabled then return end
        local text = extractMessage(...)
        -- einzelne Wörter sind Code-Fragmente, keine Rätsel: bewusst ignoriert
        if #text < 8 or #text > MAX_QUESTION_LENGTH or not text:find("%s") then return end
        if not PHANTIX_ENGINE.looksLikeRiddle(text) then return end
        local key = text:lower()
        if recentAnnouncements[key] then return end
        recentAnnouncements[key] = true
        task.delay(20, function() recentAnnouncements[key] = nil end)
        PHANTIX_SOLVER.solve(text, "announcement")
    end

    local function isRemote(value)
        return typeof(value) == "Instance" and (value:IsA("RemoteEvent") or value:IsA("UnreliableRemoteEvent"))
    end

    local function resolveNotifyRemote()
        local shared = env.PhiNotifyRemote
        if isRemote(shared) then return shared end

        local ReplicatedStorage = game:GetService("ReplicatedStorage")
        local getUpvalues = (debug and debug.getupvalues) or getupvalues
        local getConnections = getconnections or (debug and debug.getconnections)

        -- 1) NotificationController laden und die Remote aus seinen Upvalues lesen
        local controllers = ReplicatedStorage:FindFirstChild("Controllers")
        local notification = controllers and controllers:FindFirstChild("NotificationController", true)
        if notification and type(getUpvalues) == "function" then
            local okRequire, controller = pcall(require, notification)
            if okRequire and type(controller) == "table" and type(controller.Start) == "function" then
                local okValues, values = pcall(getUpvalues, controller.Start)
                if okValues and type(values) == "table" then
                    for _, value in pairs(values) do
                        if isRemote(value) then return value end
                    end
                end
            end
        end

        -- 2) Net-Remotes durchsuchen, deren Verbindung aus dem NotificationController stammt
        local packages = ReplicatedStorage:WaitForChild("Packages", 6)
        local net = packages and packages:WaitForChild("Net", 6)
        local getInfo = debug and (debug.getinfo or debug.info)
        if net and type(getInfo) == "function" and type(getConnections) == "function" then
            for _, remote in ipairs(net:GetDescendants()) do
                if remote:IsA("RemoteEvent") then
                    local okConnections, connections = pcall(getConnections, remote.OnClientEvent)
                    if okConnections and type(connections) == "table" then
                        for _, connection in ipairs(connections) do
                            local okFunction, callback = pcall(function() return connection.Function end)
                            if okFunction and type(callback) == "function" then
                                local okInfo, info = pcall(getInfo, callback)
                                if okInfo and type(info) == "table"
                                    and tostring(info.short_src or info.source or ""):find("NotificationController", 1, true) then
                                    return remote
                                end
                            end
                        end
                    end
                end
            end
        end
        return nil
    end

    local function stopListening()
        if listenerConnection then
            pcall(function() listenerConnection:Disconnect() end)
            listenerConnection = nil
        end
    end

    local function setSniperCard(on)
        SniperStatVal.Text = on and "ON" or "OFF"
        SniperStatVal.TextColor3 = on and Theme.Emerald or Theme.Dim
    end

    function PHANTIX_SOLVER.setListener(enabled)
        enabled = enabled == true
        listenerEnabled = enabled
        setSniperCard(enabled)
        if not enabled then
            stopListening()
            logLine("Riddle Listener OFF.", Theme.Dim)
            return
        end
        logLine("Riddle Listener ON. Searching for the announcement receiver…", Theme.Emerald)
        if listenerConnection or listenerResolving then return end
        listenerResolving = true
        local myGeneration = generation
        task.spawn(function()
            local okResolve, remote = pcall(resolveNotifyRemote)
            listenerResolving = false
            if not listenerEnabled or generation ~= myGeneration then return end
            if not okResolve or not remote then
                logLine("Announcement receiver not found. The manual riddle input still works.", Theme.Warn)
                return
            end
            local okConnect, connection = pcall(function()
                return remote.OnClientEvent:Connect(function(...)
                    pcall(onAnnouncement, ...)
                end)
            end)
            if not okConnect or not connection then
                logLine("Could not connect to the announcement receiver.", Theme.Red)
                return
            end
            listenerConnection = connection
            logLine("Listener attached: " .. remote.Name .. ".", Theme.Emerald)
        end)
    end

    function PHANTIX_SOLVER.setAi(enabled)
        aiEnabled = enabled == true
        if aiEnabled then
            logLine("AI fallback ON. Riddles missing in the local database are sent to Cloudflare.", Theme.Emerald)
            if not getToken() then
                logLine("No AI token set yet. Use getgenv().PHANTIX_AUTH_TOKEN or AI_CONFIG.AuthToken (see file header).", Theme.Warn)
            end
        else
            generation = generation + 1 -- späte Antworten verwerfen
            logLine("AI fallback OFF. No further Cloudflare requests.", Theme.Dim)
        end
    end

    function PHANTIX_SOLVER.shutdown()
        aiEnabled = false
        listenerEnabled = false
        generation = generation + 1
        stopListening()
    end
end

