-- ── Hintergrundbild laden: Ergebnis steht in der Console ─────────────────
local function runWithTimeout(seconds, work)
    local finished = false
    task.spawn(function()
        pcall(work)
        finished = true
    end)
    local startedAt = os.clock()
    while not finished and os.clock() - startedAt < seconds do
        task.wait(0.1)
    end
    return finished
end

local function loadBackgroundImage()
    if not GalaxyImage then return end

    local assetNumber = tostring(GALAXY_ASSET_ID):match("%d+")
    if not assetNumber then
        logLine("Background: no valid asset ID set.", Theme.Warn)
        return
    end
    logLine("Background: loading " .. GALAXY_ASSET_ID, Theme.Dim)

    local candidates = {}

    -- Ist die ID ein Decal, liefert das Decal die echte Bild-URL (falls GetObjects verfügbar ist).
    local objects
    runWithTimeout(8, function()
        objects = game:GetObjects("rbxassetid://" .. assetNumber)
    end)
    if type(objects) == "table" then
        for _, object in ipairs(objects) do
            local okTexture, texture = pcall(function()
                if object:IsA("Decal") or object:IsA("Texture") then
                    return object.Texture
                end
                return nil
            end)
            if okTexture and type(texture) == "string" and texture ~= "" then
                table.insert(candidates, { texture, "decal image" })
            end
            pcall(function() object:Destroy() end)
        end
    end
    table.insert(candidates, { GALAXY_ASSET_ID, "rbxassetid" })
    table.insert(candidates, { "http://www.roblox.com/asset/?id=" .. assetNumber, "asset url" })

    for _, candidate in ipairs(candidates) do
        if not GalaxyImage.Parent then return end
        local image, label = candidate[1], candidate[2]

        GalaxyImage.Image = image
        local fetchOk
        local finished = runWithTimeout(10, function()
            ContentProvider:PreloadAsync({ GalaxyImage }, function(_, status)
                fetchOk = (status == Enum.AssetFetchStatus.Success)
            end)
        end)

        if fetchOk == true or GalaxyImage.IsLoaded then
            logLine("Background loaded (" .. label .. ").", Theme.Emerald)
            return
        end

        local reason = "timeout"
        if finished then
            reason = (fetchOk == false) and "fetch failed" or "no result"
        end
        logLine("Background attempt '" .. label .. "' failed: " .. reason .. ".", Theme.Warn)
    end

    GalaxyImage.Image = ""
    logLine("Background not loadable — procedural nebula stays.", Theme.Red)
    logLine("Check asset type, moderation status and access in Creator Hub.", Theme.Dim)
end

-- ── Titel-Logo laden: Text-Titel bleibt sichtbar, bis das Bild wirklich geladen ist ──
-- Ein Durchlauf, keine Wiederholungen: Decal-Prüfung, dann direkter Ladeweg, dann Asset-URL.
local function loadTitleImage()
    local assetNumber = tostring(TITLE_ASSET_ID):match("%d+")
    if not assetNumber or #assetNumber < 5 then
        logLine("Title: invalid asset ID — text title stays.", Theme.Red)
        return
    end
    logLine("Title: loading " .. TITLE_ASSET_ID, Theme.Dim)

    local candidates = {}
    local wrongType

    -- Ist die ID ein Decal, liefert das Decal die echte Bild-URL (falls GetObjects verfügbar ist).
    local objects
    runWithTimeout(8, function()
        objects = game:GetObjects("rbxassetid://" .. assetNumber)
    end)
    if type(objects) == "table" and #objects > 0 then
        for _, object in ipairs(objects) do
            local okInfo, className, texture = pcall(function()
                local imageLike = object:IsA("Decal") or object:IsA("Texture")
                return object.ClassName, imageLike and object.Texture or nil
            end)
            if okInfo and type(texture) == "string" and texture ~= "" then
                logLine("Title: ID is a Decal — using its image.", Theme.Dim)
                table.insert(candidates, { texture, "decal image", false })
            elseif okInfo then
                wrongType = tostring(className)
            end
            pcall(function() object:Destroy() end)
        end
        if wrongType and #candidates == 0 then
            logLine("Title: asset is a " .. wrongType .. ", not an Image or Decal.", Theme.Warn)
        end
    else
        logLine("Title: Decal check gave no result — trying direct load.", Theme.Dim)
    end
    -- Bei den direkten Wegen muss das Bild nachweislich geladen sein (IsLoaded):
    -- ein erfolgreicher Abruf allein beweist nicht, dass es auch angezeigt wird.
    table.insert(candidates, { TITLE_ASSET_ID, "rbxassetid", true })
    table.insert(candidates, { "http://www.roblox.com/asset/?id=" .. assetNumber, "asset url", true })

    local sawFailure, sawTimeout, sawFetchedNotShown = false, false, false
    for _, candidate in ipairs(candidates) do
        if not BrandLogo.Parent then return end
        local image, label, strict = candidate[1], candidate[2], candidate[3]

        BrandLogo.Image = image
        BrandGlow.Image = image
        local fetchOk
        local statusName = "none"
        local finished = runWithTimeout(10, function()
            ContentProvider:PreloadAsync({ BrandLogo }, function(_, status)
                fetchOk = (status == Enum.AssetFetchStatus.Success)
                statusName = status and status.Name or "unknown"
            end)
        end)

        -- IsLoaded kann dem Abruf kurz hinterherhinken (nur warten, wenn der Abruf nicht gescheitert ist).
        if fetchOk ~= false then
            local startedAt = os.clock()
            while not BrandLogo.IsLoaded and os.clock() - startedAt < 3 do
                task.wait(0.1)
            end
        end

        if BrandLogo.IsLoaded or (fetchOk == true and not strict) then
            if not BrandLogo.Parent then return end
            titleActive = true
            BrandLogo.ImageTransparency = 0
            BrandGlow.ImageTransparency = TITLE_GLOW_TRANSPARENCY
            Brand.Visible = false
            Subtitle.Position = UDim2.fromOffset(26, 41)
            applyTitleLayout(minimised)
            local size = BrandLogo.AbsoluteSize
            logLine(string.format("Title logo loaded (%s), %.0fx%.0f px on screen.", label, size.X, size.Y), Theme.Emerald)
            if size.X < 8 or size.Y < 8 then
                logLine("Title logo is unexpectedly small — check the layout.", Theme.Warn)
            end
            return
        end

        local reason
        if not finished then
            sawTimeout = true
            reason = "timeout"
        elseif fetchOk == false then
            sawFailure = true
            reason = "Roblox status " .. statusName
        elseif fetchOk == true then
            sawFetchedNotShown = true
            reason = "fetched but not displayed"
        else
            reason = "no result"
        end
        logLine("Title attempt '" .. label .. "' failed: " .. reason .. ".", Theme.Warn)
    end

    BrandLogo.Image = ""
    BrandGlow.Image = ""
    logLine("Title logo not loadable — text title stays.", Theme.Red)
    if wrongType and not sawFetchedNotShown then
        logLine("Cause: the asset is a " .. wrongType .. ", not an Image.", Theme.Dim)
    elseif sawFetchedNotShown then
        logLine("Cause not confirmed: fetched, but not shown (Decal/Model, private or moderated?).", Theme.Dim)
    elseif sawFailure then
        logLine("Cause: Roblox could not load it (wrong ID type, private or moderated?).", Theme.Dim)
    elseif sawTimeout then
        logLine("Cause unknown: timeout (network or asset not reachable).", Theme.Dim)
    else
        logLine("Cause unknown: Roblox gave no status.", Theme.Dim)
    end
end

-- ── Initiale Logs ────────────────────────────────────────────────────────
logLine("PHANTIX " .. PHANTIX_VERSION .. " loaded — Nebula Luxe.", Theme.PurpleLight)
logLine("Header stays visible while minimized.", Theme.Emerald)
logLine("Mobile P-toggle is available on touch devices.", Theme.Dim)
logLine("Local database: " .. PHANTIX_ENGINE.dbCount .. " entries. Local answers are used first.", Theme.Emerald)
logLine("Cloudflare AI fallback is OFF. Enable it in Settings; a token is needed (see file header).", Theme.Dim)
task.spawn(loadBackgroundImage)
task.spawn(loadTitleImage)

print("[PHANTIX] " .. PHANTIX_VERSION .. " Nebula Luxe Colorwave loaded.")
